// NAME: Charger | NOTE: runs straight at you, firing the whole way
function think(s, mem, squad) {
  return { move: "advance", attack: true };
}

// NAME: Turret | NOTE: stands still and shoots whenever it sees you
function think(s, mem, squad) {
  return { move: "hold", attack: s.canSee };
}

// NAME: Drunk | NOTE: stumbles in a random direction every step
function think(s, mem, squad) {
  const moves = ["advance", "retreat", "strafeL", "strafeR", "flankL", "flankR", "hold"];
  return { move: moves[Math.floor(Math.random() * moves.length)], attack: Math.random() < 0.3 };
}

// NAME: Coward | NOTE: backs off for a couple of seconds after taking a hit
function think(s, mem, squad) {
  if (s.hurtAgo < 70) return { move: "retreat", attack: s.canShoot };
  return { move: "advance", attack: s.canShoot };
}

// NAME: Crooked Tide | NOTE: fights from about 1204 units away
function think(s, mem, squad) {
  const G = {"engage":1204,"flankAim":0,"pincer":0,"rushAfterShot":0,"retreatHp":0,"ambush":0,"sneaky":0,"squad":0};
  const side = G.pincer ? (s.uid % 2 ? "L" : "R") : "L";
  const offScreen = s.aimOffset > 45;
  if (s.hp < s.maxHp * G.retreatHp && s.hurtAgo < 70) return { move: "retreat", attack: s.canShoot };
  if (G.ambush > 0 && s.aliveTics < G.ambush && offScreen) return { move: "hold", attack: false };
  if (G.rushAfterShot > 0 && s.playerFiredAgo < G.rushAfterShot) return { move: "flank" + side, attack: true };
  if (s.canSee && s.aimOffset < G.flankAim) return { move: "strafe" + side, attack: s.canShoot && !G.sneaky };
  if (s.alliesNear < G.squad && s.dist > 400) return { move: "hold", attack: s.canShoot && !G.sneaky };
  const attack = s.canMelee || (s.canShoot && (!G.sneaky || offScreen));
  if (s.dist > G.engage) return { move: "advance", attack };
  if (s.dist < G.engage * 0.5) return { move: "retreat", attack };
  return { move: "flank" + side, attack };
}

